1	package com.ahope.ds.blackbox;
2	
3	import java.io.ByteArrayOutputStream;
4	import java.io.InputStream;
5	import java.nio.charset.StandardCharsets;
6	import java.sql.Connection;
7	import java.sql.Statement;
8	
9	/**
10	 * JDK 8 호환 테스트 유틸리티
11	 */
12	class TestUtil {
13	
14	    static {
15	        // POST/PUT 302 redirect는 RestAssured 기본 설정으로 follow되지 않음
16	        // 각 테스트에서 .redirects().follow(true)를 명시하거나, 302를 기대하도록 설계
17	    }
18	
19	    static byte[] readAllBytes(InputStream is) throws Exception {
20	        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
21	        byte[] data = new byte[4096];
22	        int bytesRead;
23	        while ((bytesRead = is.read(data, 0, data.length)) != -1) {
24	            buffer.write(data, 0, bytesRead);
25	        }
26	        return buffer.toByteArray();
27	    }
28	
29	    static void executeSql(Connection conn, String resourcePath, Class<?> clazz) {
30	        try (InputStream is = clazz.getClassLoader().getResourceAsStream(resourcePath);
31	             Statement stmt = conn.createStatement()) {
32	            String sql = new String(readAllBytes(is), StandardCharsets.UTF_8);
33	            StringBuilder cleaned = new StringBuilder();
34	            for (String rawLine : sql.split("\n")) {
35	                String line = rawLine.trim();
36	                if (line.startsWith("--") || line.isEmpty()) continue;
37	                cleaned.append(line).append(" ");
38	            }
39	            for (String statement : cleaned.toString().split(";")) {
40	                String trimmed = statement.trim();
41	                if (!trimmed.isEmpty()) stmt.execute(trimmed);
42	            }
43	        } catch (Exception e) {
44	            throw new RuntimeException("SQL execution failed: " + resourcePath, e);
45	        }
46	    }
47	
48	    static String readResource(String resourcePath, Class<?> clazz) {
49	        try (InputStream is = clazz.getClassLoader().getResourceAsStream(resourcePath)) {
50	            return new String(readAllBytes(is), StandardCharsets.UTF_8);
51	        } catch (Exception e) {
52	            throw new RuntimeException("Resource read failed: " + resourcePath, e);
53	        }
54	    }
55	
56	    /**
57	     * 관리자 로그인 세션을 획득하여 SESSION 쿠키를 반환한다.
58	     * 1단계: POST /web/login/ajax (id, pw) → accountSeq 반환
59	     * 2단계: JDBC로 ACCOUNT_SMS에서 인증번호 조회
60	     * 3단계: POST /web/login/sms (accountSeq, certificationNo) → 세션 생성
61	     * 3-B단계: 약관 동의가 필요하면 POST /web/login/agreeTerms 호출
62	     * 4단계: tokenErr="001"이면 POST /web/login/token 호출하여 loginToken 발급
63	     *
64	     * @param baseUrl 서버 URL (예: http://localhost:8080)
65	     * @param id 관리자 ID
66	     * @param pw 관리자 비밀번호
67	     * @param conn DB 연결
68	     * @return SESSION 쿠키 값
69	     */
70	    static String adminLogin(String baseUrl, String id, String pw, Connection conn) {
71	        // 1단계: 로그인 시도 → SMS 인증번호 발송 + accountSeq 반환
72	        io.restassured.response.Response loginResp = io.restassured.RestAssured.given()
73	            .baseUri(baseUrl)
74	            .header("X-Requested-With", "XMLHttpRequest")
75	            .contentType("application/x-www-form-urlencoded")
76	            .formParam("id", id)
77	            .formParam("pw", pw)
78	        .when()
79	            .post("/web/login/ajax");
80	
81	        String err = loginResp.jsonPath().getString("err");
82	        if (!"000".equals(err)) {
83	            throw new RuntimeException("Login step 1 failed: err=" + err);
84	        }
85	        long accountSeq = loginResp.jsonPath().getLong("accountSeq");
86	
87	        // SESSION는 1단계에서 발급됨 — 이후 모든 요청에 이 쿠키 사용
88	        String jsessionId = loginResp.getCookie("SESSION");
89	        if (jsessionId == null || jsessionId.isEmpty()) {
90	            throw new RuntimeException("No SESSION cookie from login/ajax");
91	        }
92	
93	        // 2단계: DB에서 인증번호 직접 조회
94	        String certNo;
95	        try (java.sql.PreparedStatement ps = conn.prepareStatement(
96	                "SELECT CERTIFICATION_NO FROM ACCOUNT_SMS WHERE ACCOUNT_SEQ = ?")) {
97	            ps.setLong(1, accountSeq);
98	            java.sql.ResultSet rs = ps.executeQuery();
99	            if (!rs.next()) throw new RuntimeException("No SMS info found for accountSeq=" + accountSeq);
100	            certNo = rs.getString(1);
101	        } catch (Exception e) {
102	            throw new RuntimeException("Failed to read SMS certification", e);
103	        }
104	
105	        // 3단계: SMS 인증 → 세션 생성
106	        io.restassured.response.Response smsResp = io.restassured.RestAssured.given()
107	            .baseUri(baseUrl)
108	            .cookie("SESSION", jsessionId)
109	            .header("X-Requested-With", "XMLHttpRequest")
110	            .contentType("application/x-www-form-urlencoded")
111	            .formParam("id", id)
112	            .formParam("pw", pw)
113	            .formParam("accountSeq", accountSeq)
114	            .formParam("certificationNo", certNo)
115	        .when()
116	            .post("/web/login/sms");
117	
118	        String smsErr = smsResp.jsonPath().getString("err");
119	        if (!"000".equals(smsErr)) {
120	            throw new RuntimeException("Login step 2 (SMS) failed: err=" + smsErr);
121	        }
122	
123	        // 3-B단계: 약관 동의가 필요한 경우 (AUTHZ가 01, 07이 아닌 계정)
124	        String termsJson = smsResp.jsonPath().getString("terms");
125	        if (termsJson != null) {
126	            long mngAgreeTermsSeq = smsResp.jsonPath().getLong("terms.latestTerms.mngAgreeTermsSeq");
127	            int version = smsResp.jsonPath().getInt("terms.latestTerms.version");
128	
129	            io.restassured.response.Response agreeResp = io.restassured.RestAssured.given()
130	                .baseUri(baseUrl)
131	                .cookie("SESSION", jsessionId)
132	                .header("X-Requested-With", "XMLHttpRequest")
133	                .contentType("application/x-www-form-urlencoded")
134	                .formParam("id", id)
135	                .formParam("pw", pw)
136	                .formParam("accountSeq", accountSeq)
137	                .formParam("mngAgreeTermsSeq", mngAgreeTermsSeq)
138	                .formParam("version", version)
139	            .when()
140	                .post("/web/login/agreeTerms");
141	
142	            String agreeErr = agreeResp.jsonPath().getString("err");
143	            if (agreeErr != null && !"000".equals(agreeErr)) {
144	                String agreeErrMsg = agreeResp.jsonPath().getString("errMsg");
145	                // errMsg가 숫자 코드(100, 200 등)이면 정상 로그인 완료
146	                if (agreeErrMsg == null || (!agreeErrMsg.matches("\\d+") && !"success".equalsIgnoreCase(agreeErrMsg))) {
147	                    throw new RuntimeException("Login step 3-B (agreeTerms) failed: err=" + agreeErr + ", errMsg=" + agreeErrMsg);
148	                }
149	            }
150	
151	            // agreeTerms 응답에서 tokenErr 확인
152	            String tokenErr = agreeResp.jsonPath().getString("tokenErr");
153	            if ("001".equals(tokenErr)) {
154	                // 이미 로그인된 세션이 있어 loginToken이 설정되지 않음 → token 발급 요청
155	                io.restassured.RestAssured.given()
156	                    .baseUri(baseUrl)
157	                    .cookie("SESSION", jsessionId)
158	                    .header("X-Requested-With", "XMLHttpRequest")
159	                    .contentType("application/x-www-form-urlencoded")
160	                .when()
161	                    .post("/web/login/token");
162	            }
163	        } else {
164	            // 약관 동의 불필요 — tokenErr 확인
165	            String tokenErr = smsResp.jsonPath().getString("tokenErr");
166	            if ("001".equals(tokenErr)) {
167	                io.restassured.RestAssured.given()
168	                    .baseUri(baseUrl)
169	                    .cookie("SESSION", jsessionId)
170	                    .header("X-Requested-With", "XMLHttpRequest")
171	                    .contentType("application/x-www-form-urlencoded")
172	                .when()
173	                    .post("/web/login/token");
174	            }
175	        }
176	
177	        return jsessionId;
178	    }
179	
180	    /**
181	     * 서버의 가입자 등록 API를 통해 가입자를 등록하고, DB에서 암호화된 CTN을 반환한다.
182	     * SecurityModule 의존 테스트의 setup 데이터 준비에 사용.
183	     *
184	     * @param baseUrl 서버 URL
185	     * @param sessionId JOIN 관리자(AUTHZ=05) 세션 ID
186	     * @param ctn 평문 전화번호 (예: "01012345678")
187	     * @param corporationYn "1"(법인) 또는 "0"(개인)
188	     * @param managerName 관리자명
189	     * @param conn DB 연결
190	     * @return 서버가 암호화한 CTN 값
191	     */
192	    static String createMemberAndGetEncryptedCtn(String baseUrl, String sessionId, String ctn,
193	            String corporationYn, String managerName, Connection conn) {
194	        io.restassured.RestAssured.given()
195	            .baseUri(baseUrl)
196	            .cookie("SESSION", sessionId)
197	            .header("X-Requested-With", "XMLHttpRequest")
198	            .contentType("multipart/form-data")
199	            .multiPart("ctn", ctn)
200	            .multiPart("exceptionPolicy", "0")
201	            .multiPart("managerName", managerName)
202	            .multiPart("corporationYn", corporationYn)
203	            .multiPart("immediately", "false")
204	            .multiPart("noteLen", "0")
205	        .when().post("/web/admin/members/");
206	
207	        try (java.sql.PreparedStatement ps = conn.prepareStatement(
208	                "SELECT CTN FROM MEMBER ORDER BY MEMBER_SEQ DESC LIMIT 1")) {
209	            java.sql.ResultSet rs = ps.executeQuery();
210	            if (rs.next()) {
211	                return rs.getString("CTN");
212	            }
213	            throw new RuntimeException("Member not found after creation: ctn=" + ctn);
214	        } catch (RuntimeException e) {
215	            throw e;
216	        } catch (Exception e) {
217	            throw new RuntimeException("Failed to read encrypted CTN", e);
218	        }
219	    }
220	
221	    // =========================================================================
222	    // AWS Encryption SDK 기반 CTN 암호화 유틸리티
223	    // =========================================================================
224	
225	    private static com.amazonaws.encryptionsdk.AwsCrypto awsCrypto;
226	    private static com.amazonaws.encryptionsdk.caching.CachingCryptoMaterialsManager cachingCmm;
227	
228	    /**
229	     * AWS Encryption SDK를 사용하여 평문을 암호화한다.
230	     * 서버의 AwsKmsEncryptionService와 동일한 방식 (Envelope Encryption + Base64).
231	     * LocalStack KMS의 cmk-2 (dataEncryptionService용)를 사용한다.
232	     *
