package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.hasSize;

import java.sql.Connection;
import java.sql.DriverManager;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.MethodOrderer;
import org.junit.jupiter.api.Order;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestMethodOrder;

/**
 * Black-Box API Integration Test — Client V2 API 동기화
 *
 * @target-controller ClientAPIController (/client)
 * @target-api GET /client/sync
 *
 * 인증: ClientLoginInterceptor - Authorization: Bearer {ACCESS_TOKEN} (AWS Encryption SDK, CMK-4)
 * 필수 헤더: X-Manufacturer, X-Model, X-OS-Version, X-App-Version, Authorization
 */
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class ClientSyncBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static final DateTimeFormatter TOKEN_DATE_FORMAT = DateTimeFormatter.ofPattern("yyyyMMddHHmmss");
    private static Connection dbConnection;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/client-sync-teardown.sql", ClientSyncBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/client-sync-setup.sql", ClientSyncBlackBoxTest.class);
        // ECGI 컬럼을 LocalStack KMS(CMK-1)로 암호화 — 서버가 응답 시 decrypt하므로 필수
        TestUtil.encryptEcgi(dbConnection, 965012, "9998887770");
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/client-sync-teardown.sql", ClientSyncBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    private static String futureExpiry() {
        return LocalDateTime.now().plusDays(1).format(TOKEN_DATE_FORMAT);
    }

    private static String pastExpiry() {
        return LocalDateTime.now().minusDays(1).format(TOKEN_DATE_FORMAT);
    }

    // ==================== NTC — 정상 동기화 (솔루션 활성) ====================

    @Test @Order(1)
    void NTC_sync_success() {
        String token = TestUtil.buildClientBearerToken(96501, 96501, "ACCESS", futureExpiry());

        given().log().all().baseUri(BASE_URL)
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
            .header("Authorization", token)
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("000"))
            .body("data.latestTermsVersion", equalTo(77))
            .body("data.latestNoticeVersion", equalTo(900001001))
            .body("data.mainBackgroundImageUrl", equalTo("https://test.example.com/bg.png"))
            .body("data.interlockingAppList", hasSize(1))
            .body("data.interlockingAppList[0].appName", equalTo("SyncApp"))
            .body("data.interlockingAppList[0].packageName", equalTo("com.test.syncapp"))
            .body("data.allowedEcgiList", hasSize(1))
            .body("data.allowedEcgiList[0]", equalTo("9998887770"))
            .body("data.solutionList", hasSize(1))
            .body("data.solutionList[0].solutionId", equalTo(96501))
            .body("data.solutionList[0].solutionName", equalTo("SyncTestSolution"))
            .body("data.solutionList[0].enabled", equalTo(true));
    }

    // ==================== NTC — 금지 솔루션 가입자: enabled=false ====================

    @Test @Order(2)
    void NTC_sync_bannedSolution_disabled() {
        String token = TestUtil.buildClientBearerToken(96502, 96501, "ACCESS", futureExpiry());

        given().log().all().baseUri(BASE_URL)
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
            .header("Authorization", token)
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("000"))
            .body("data.solutionList", hasSize(1))
            .body("data.solutionList[0].solutionId", equalTo(96501))
            .body("data.solutionList[0].enabled", equalTo(false));
    }

    // ==================== NTC — 연동앱/ECGI/솔루션 없는 고객사: 빈 리스트 ====================

    @Test @Order(3)
    void NTC_sync_noRelatedData_emptyLists() {
        String token = TestUtil.buildClientBearerToken(96503, 96502, "ACCESS", futureExpiry());

        given().log().all().baseUri(BASE_URL)
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
            .header("Authorization", token)
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("000"))
            .body("data.mainBackgroundImageUrl", equalTo("https://test.example.com/bg2.png"))
            .body("data.interlockingAppList", hasSize(0))
            .body("data.allowedEcgiList", hasSize(0))
            .body("data.solutionList", hasSize(0));
    }

    // ==================== ATC — Authorization 헤더 누락 ====================

    @Test @Order(4)
    void ATC_missingAuthorizationHeader() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("816"))
            .body("message", equalTo("MISSING_TOKEN_VALUE"));
    }

    // ==================== ATC — Authorization 헤더가 "Bearer " 형식이 아님 ====================

    @Test @Order(5)
    void ATC_invalidTokenFormat_noBearerPrefix() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
            .header("Authorization", "InvalidTokenWithoutBearerPrefix")
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("812"))
            .body("message", equalTo("INVALID_TOKEN"));
    }

    // ==================== ATC — 복호화 불가능한 토큰 (KMS decrypt 실패) ====================

    @Test @Order(6)
    void ATC_invalidToken_undecryptable() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
            .header("Authorization", "Bearer bm90LWEtdmFsaWQtZW5jcnlwdGVkLW1lc3NhZ2U=")
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("812"))
            .body("message", equalTo("INVALID_TOKEN"));
    }

    // ==================== ATC — 만료된 토큰 ====================

    @Test @Order(7)
    void ATC_expiredToken() {
        String token = TestUtil.buildClientBearerToken(96501, 96501, "ACCESS", pastExpiry());

        given().log().all().baseUri(BASE_URL)
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
            .header("Authorization", token)
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("802"))
            .body("message", equalTo("TOKEN_EXPIRED"));
    }

    // ==================== ATC — tokenType이 ACCESS가 아님 ====================

    @Test @Order(8)
    void ATC_invalidTokenType() {
        String token = TestUtil.buildClientBearerToken(96501, 96501, "REFRESH", futureExpiry());

        given().log().all().baseUri(BASE_URL)
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
            .header("Authorization", token)
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("855"))
            .body("message", equalTo("INVALID_TOKEN_TYPE"));
    }

