        TestUtil.encryptEcgi(dbConnection, 965012, "9998887770");
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/client-sync-teardown.sql", ClientSyncBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    private static String futureExpiry() {
        return LocalDateTime.now().plusDays(1).format(TOKEN_DATE_FORMAT);
    }

    private static String pastExpiry() {
        return LocalDateTime.now().minusDays(1).format(TOKEN_DATE_FORMAT);
    }

    // ==================== NTC — 정상 동기화 (솔루션 활성) ====================

    @Test @Order(1)
    void NTC_sync_success() {
