// ========== 고객사 해지/복원 추가 분기 커버 ==========

/**
 * [ATC_cancelClient_alreadyRequested] 이미 해지요청(02) 상태에서 cancel 재호출
 * ClientService.modifyClientCancel은 cancelStatus가 01(JOIN) 또는 06(CANCEL)일 때만 진행하고,
 * 그 외 상태(02 등)에서는 "Request service is already being processed." err=007을 반환한다.
 * 즉 현재 ClientService 구현에는 별도의 'immediately' 분기가 없어 02→007이 정상 동작이다.
 */
@Test
void NTC_cancelClient_immediately() {
    // 해지 요청 상태(02)로 변경
    try (java.sql.Statement stmt = dbConnection.createStatement()) {
        stmt.execute("UPDATE CLIENT SET CANCEL_STATUS = '02' WHERE CLIENT_SEQ = 97010");
    } catch (Exception e) { throw new RuntimeException(e); }

    try {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("immediately", "true")
        .when().put("/web/super/admin/clients/97010/cancel")
        .then().log().all().statusCode(200)
            .body("err", equalTo("007"));
    } finally {
        // 복원
        try (java.sql.Statement stmt = dbConnection.createStatement()) {
            stmt.execute("UPDATE CLIENT SET CANCEL_STATUS = '01' WHERE CLIENT_SEQ = 97010");
        } catch (Exception e) { /* ignore */ }
    }
}

/** [NTC_cancelClient_request] 해지 요청 — modifyClientCancel 요청 분기 */
@Test
void NTC_cancelClient_request() {
    given().log().all().baseUri(BASE_URL)
        .cookie("SESSION", sessionId)
        .header("X-Requested-With", "XMLHttpRequest")
        .contentType("application/x-www-form-urlencoded")
        .formParam("immediately", "false")
    .when().put("/web/super/admin/clients/97010/cancel")
    .then().log().all().statusCode(200)
        .body("err", equalTo("000"));

    // 복원
    try (java.sql.Statement stmt = dbConnection.createStatement()) {
        stmt.execute("UPDATE CLIENT SET CANCEL_STATUS = '01' WHERE CLIENT_SEQ = 97010");
    } catch (Exception e) { throw new RuntimeException(e); }
}

