import org.junit.jupiter.api.MethodOrderer;
import org.junit.jupiter.api.Order;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestMethodOrder;

/**
 * Black-Box API Integration Test — 슈퍼관리자 고객사 해지 (추가 분기 커버리지)
 *
 * @target-controller ClientController (/web/super/admin/clients)
 * @target-api PUT /web/super/admin/clients/{clientSeq}/cancel
 *
 * NOTE: AdminClientListBlackBoxTest가 CANCEL_STATUS 01->02(err=000)/02 재호출(err=007) 분기를
 * 이미 커버하고 있다. 이 테스트는 그 파일이 다루지 않는 나머지 분기를 커버한다:
 *   - CANCEL_STATUS=06(해지) 상태에서 cancel 호출 -> 즉시 전체 캐스케이드 삭제(err=000, deleteCount 반환)
 *   - LPS 등록(진행중) 가입자가 있는 고객사 -> err=001로 차단 (LPS 체크가 cancelStatus 조회보다 먼저 수행됨)
 *   - 세션 없이 호출 -> 401
 */
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class ClientCancelBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/client-cancel-teardown.sql", ClientCancelBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/client-cancel-setup.sql", ClientCancelBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "clientcanceladmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/client-cancel-teardown.sql", ClientCancelBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    // ==================== NTC — CANCEL_STATUS=06(해지) 상태: 즉시 캐스케이드 삭제 ====================

    @Test @Order(1)
    void NTC_cancelClient_fromCancelStatus_cascadeDelete() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().put("/web/super/admin/clients/97521/cancel")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"))
            .body("deleteCount", equalTo(1));

        // 캐스케이드 삭제 검증: CLIENT/MEMBER 행이 실제로 삭제되어야 한다
        try (java.sql.PreparedStatement ps = dbConnection.prepareStatement(
                "SELECT COUNT(*) FROM CLIENT WHERE CLIENT_SEQ = 97521")) {
            java.sql.ResultSet rs = ps.executeQuery();
            rs.next();
            org.junit.jupiter.api.Assertions.assertEquals(0, rs.getInt(1));
        } catch (Exception e) { throw new RuntimeException(e); }
    }

    // ==================== NTC — LPS 등록(진행중) 가입자 존재: err=001로 차단 ====================

    @Test @Order(2)
    void NTC_cancelClient_lpsJoinedMemberExists_blocked() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().put("/web/super/admin/clients/97522/cancel")
        .then().log().all().statusCode(200)
            .body("err", equalTo("001"))
            .body("errMsg", equalTo("UNABLE_TO_CLIENT_CANCEL_BECAUSE_EXIST_JOINED_MEMBER_IN_THE_LPS"));

        // 차단되었으므로 CLIENT는 그대로 유지되어야 한다 (CANCEL_STATUS 변경 없음)
        try (java.sql.PreparedStatement ps = dbConnection.prepareStatement(
                "SELECT CANCEL_STATUS FROM CLIENT WHERE CLIENT_SEQ = 97522")) {
            java.sql.ResultSet rs = ps.executeQuery();
            rs.next();
            org.junit.jupiter.api.Assertions.assertEquals("01", rs.getString(1));
        } catch (Exception e) { throw new RuntimeException(e); }
    }

    // ==================== ATC — 세션 없이 호출 ====================

    @Test @Order(3)
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().put("/web/super/admin/clients/97521/cancel")
        .then().log().all().statusCode(401);
    }
}

