package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.MethodOrderer;
import org.junit.jupiter.api.Order;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestMethodOrder;

/**
 * Black-Box API Integration Test — 슈퍼관리자 개인정보 복호화
 *
 * @target-controller CryptoController (/web/super/admin/crypto)
 * @target-api POST /web/super/admin/crypto/personal
 *
 * DB 조회 없이 AWS Encryption SDK(CMK-2, dataEncryptionService)로 cryptoContent를 복호화만 하는 API.
 * TestUtil.kmsEncrypt()가 동일 CMK-2로 암호화하므로 그 결과를 cryptoContent로 사용하면 서버가 복호화 가능하다.
 */
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class CryptoPersonalBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/crypto-personal-teardown.sql", CryptoPersonalBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/crypto-personal-setup.sql", CryptoPersonalBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "cryptoadmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/crypto-personal-teardown.sql", CryptoPersonalBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    // ==================== NTC — 정상 복호화 (CTN 형식) ====================

    @Test @Order(1)
    void NTC_personalDecryption_ctn_success() {
        String cipherText = TestUtil.kmsEncrypt("01099998888");

        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", cipherText)
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo("01099998888"));
    }

    // ==================== NTC — 정상 복호화 (임의 개인정보 문자열) ====================

    @Test @Order(2)
    void NTC_personalDecryption_arbitraryText_success() {
        String cipherText = TestUtil.kmsEncrypt("Hong Gil Dong / hgd@test.com");

        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", cipherText)
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo("Hong Gil Dong / hgd@test.com"));
    }

    // ==================== NTC — 공백만 있는 값: trim() 후 빈 문자열 복호화(정상, 빈 결과) ====================

    @Test @Order(3)
    void NTC_personalDecryption_whitespaceContent_emptyResult() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", "   ")
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo(""));
    }

    // ==================== VTC — cryptoContent 파라미터 자체가 없음 ====================

    @Test @Order(4)
    void VTC_cryptoContent_NULL() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("001"))
            .body("errMsg", equalTo("MISSING_REQUIRED_VALUE : [cryptoContent]"));
    }

    // ==================== VTC — cryptoContent="" (빈 문자열) ====================

    @Test @Order(5)
    void VTC_cryptoContent_EMPTY() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", "")
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("001"))
            .body("errMsg", equalTo("MISSING_REQUIRED_VALUE : [cryptoContent]"));
    }

    // ==================== VTC — 복호화 불가능한 값 (KMS decrypt 실패) ====================

    @Test @Order(6)
    void VTC_cryptoContent_invalidCiphertext() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", "not-a-valid-encrypted-message")
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("115"));
    }

    // ==================== ATC — 세션 없이 호출 ====================

    @Test @Order(7)
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", "irrelevant")
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(401);
    }
}

