package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.MethodOrderer;
import org.junit.jupiter.api.Order;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestMethodOrder;

/**
 * Black-Box API Integration Test — ECGI 목록 조회 (페이징/스코프 커버리지)
 *
 * @target-controller ECGIController (/web/admin/ecgis)
 * @target-api GET /web/admin/ecgis/ajax
 *
 * NOTE: AdminEcgiBlackBoxTest가 1건짜리 기본 목록 조회를 이미 커버하고 있다.
 * 이 테스트는 그 파일이 다루지 않는 분기를 커버한다:
 *   - length 파라미터 생략/‑1: LIMIT/OFFSET 없이 전체 조회
 *   - length/start 페이징: LIMIT #{length} OFFSET #{start}
 *   - clientSeq 스코프 격리: 다른 고객사의 ECGI는 목록에 나타나지 않음(세션의 loginClientSeq로만 필터링)
 */
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class AdminEcgiListBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/admin-ecgi-list-teardown.sql", AdminEcgiListBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-ecgi-list-setup.sql", AdminEcgiListBlackBoxTest.class);
        TestUtil.encryptEcgi(dbConnection, 975411, "1110001111");
        TestUtil.encryptEcgi(dbConnection, 975412, "2220002222");
        TestUtil.encryptEcgi(dbConnection, 975413, "3330003333");
        TestUtil.encryptEcgi(dbConnection, 975421, "9990009999");
        sessionId = TestUtil.adminLogin(BASE_URL, "ecgilistadmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/admin-ecgi-list-teardown.sql", AdminEcgiListBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    // ==================== NTC — length 파라미터 생략: 전체 3건, 다른 고객사 데이터 제외 ====================

    @Test @Order(1)
    void NTC_ecgiList_noLengthParam_allRowsScopedToClient() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().get("/web/admin/ecgis/ajax")
        .then().log().all().statusCode(200)
            .body("iTotalRecords", equalTo(3))
            .body("aaData.size()", equalTo(3))
            .body("aaData[0].name", equalTo("EcgiC"))
            .body("aaData[0].ecgi", equalTo("3330003333"))
            .body("aaData[1].name", equalTo("EcgiB"))
            .body("aaData[2].name", equalTo("EcgiA"));
    }

    // ==================== VTC — length=-1: LIMIT 없이 전체 조회 ====================

    @Test @Order(2)
    void VTC_length_negativeOne_allRows() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("length", "-1")
            .queryParam("start", 0)
        .when().get("/web/admin/ecgis/ajax")
        .then().log().all().statusCode(200)
            .body("iTotalRecords", equalTo(3))
            .body("aaData.size()", equalTo(3));
    }

    // ==================== NTC — 페이징 첫 페이지 (length=2, start=0) ====================

    @Test @Order(3)
    void NTC_ecgiList_paginated_firstPage() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("length", 2)
            .queryParam("start", 0)
        .when().get("/web/admin/ecgis/ajax")
        .then().log().all().statusCode(200)
            .body("iTotalRecords", equalTo(3))
            .body("aaData.size()", equalTo(2))
            .body("aaData[0].name", equalTo("EcgiC"))
            .body("aaData[1].name", equalTo("EcgiB"));
    }

    // ==================== NTC — 페이징 두번째 페이지 (length=2, start=2) ====================

    @Test @Order(4)
    void NTC_ecgiList_paginated_secondPage() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("length", 2)
            .queryParam("start", 2)
        .when().get("/web/admin/ecgis/ajax")
        .then().log().all().statusCode(200)
            .body("iTotalRecords", equalTo(3))
            .body("aaData.size()", equalTo(1))
            .body("aaData[0].name", equalTo("EcgiA"))
            .body("aaData[0].ecgi", equalTo("1110001111"));
    }

    // ==================== ATC — 세션 없이 호출 ====================

    @Test @Order(5)
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().get("/web/admin/ecgis/ajax")
        .then().log().all().statusCode(401);
    }
}

