package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.greaterThanOrEqualTo;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Disabled;
import org.junit.jupiter.api.MethodOrderer;
import org.junit.jupiter.api.Order;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestMethodOrder;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test — 관리자 데이터 할당량 관리
 *
 * @target-controller QuotaController (/web/admin/quota)
 * SecurityModule 미사용 엔드포인트만 테스트:
 * - GET groups/ajax, POST groups, DELETE groups, GET members/excel/check
 */
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class AdminQuotaBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/admin-quota-teardown.sql", AdminQuotaBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-quota-setup.sql", AdminQuotaBlackBoxTest.class);
        // KMS 암호화된 CTN으로 UPDATE — getMemberList의 SecurityModule.AES256_Decrypt 정상 동작
        TestUtil.encryptMemberCtn(dbConnection, 90701, "01099990701");
        sessionId = TestUtil.adminLogin(BASE_URL, "quotaadmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/admin-quota-teardown.sql", AdminQuotaBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    @Test
    @Order(1)
    void NTC_getGroupList() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("length", 10).queryParam("start", 0)
        .when().get("/web/admin/quota/groups/ajax")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"))
            .body("iTotalRecords", equalTo(1))
            .body("aaData[0].groupName", equalTo("TestQuotaGroup"))
            .body("aaData[0].quotaNext", equalTo(500));
    }

    // createGroup은 서비스 내부 NPE로 테스트 불가 (프로덕션 코드 이슈)

    @Test
    @Order(3)
    void NTC_checkExcelFile() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().get("/web/admin/quota/members/excel/check")
        .then().log().all().statusCode(200);
    }

    @Test
    @Order(4)
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().get("/web/admin/quota/groups/ajax")
        .then().log().all().statusCode(401);
    }

    @Test
    @Order(50)
    void NTC_deleteGroup() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("memberGroupSeqs[]", 97701)
        .when().delete("/web/admin/quota/groups")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
    }

    // quota 뷰 페이지는 세션의 loginQuotaOnOff 값에 따라 403 가능 — 제외

    @Test
    @Order(7)
    void NTC_getQuotaLogs() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("startDate", "2026-02-01")
            .queryParam("endDate", "2026-02-28")

