package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.MethodOrderer;
import org.junit.jupiter.api.Order;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestMethodOrder;

/**
 * Black-Box API Integration Test — 데이터 할당 그룹 삭제 (추가 분기 커버리지)
 *
 * @target-controller QuotaController (/web/admin/quota)
 * @target-api DELETE /web/admin/quota/groups (task 명세상 "quotagroups")
 *
 * NOTE: AdminQuotaBlackBoxTest의 NTC_deleteGroup은 단일 그룹 삭제(err=000)만 커버한다.
 * 이 테스트는 그 파일이 다루지 않는 분기를 커버한다:
 *   - 다건 삭제 + removeCnt 검증 + disbandMemberGroups로 소속 가입자의 MEMBER_GROUP_SEQ가 NULL로 초기화됨(JDBC 검증)
 *   - 존재하지 않는 그룹 삭제 시도 → err=008 (GROUP_NOT_FOUND)
 *   - 필수 파라미터(memberGroupSeqs[]) 누락 → err=999 (MissingServletRequestParameterException을 CommonController가 일반 처리)
 *   - 세션 없이 호출 → 401
 */
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class QuotaDeleteGroupBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/quota-delete-group-teardown.sql", QuotaDeleteGroupBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/quota-delete-group-setup.sql", QuotaDeleteGroupBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "quotadeladmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/quota-delete-group-teardown.sql", QuotaDeleteGroupBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    // ==================== ATC — 존재하지 않는 그룹 삭제 시도 ====================

    @Test @Order(1)
    void ATC_deleteGroup_notFound() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("memberGroupSeqs[]", 999999999)
        .when().delete("/web/admin/quota/groups")
        .then().log().all().statusCode(200)
            .body("err", equalTo("008"))
            .body("errMsg", equalTo("GROUP_NOT_FOUND"));
    }

    // ==================== NTC — 다건 삭제 + removeCnt 검증 + 소속 가입자 disband 검증 ====================

    @Test @Order(2)
    void NTC_deleteGroup_multipleGroups_disbandsMembers() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("memberGroupSeqs[]", new Object[] {97771, 97772})
        .when().delete("/web/admin/quota/groups")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"))
            .body("removeCnt", equalTo(2));

        // disbandMemberGroups 검증: 그룹 A 소속이었던 가입자의 MEMBER_GROUP_SEQ가 NULL로 초기화되어야 한다
        try (java.sql.PreparedStatement ps = dbConnection.prepareStatement(
                "SELECT MEMBER_GROUP_SEQ FROM MEMBER WHERE MEMBER_SEQ = 90771")) {
            java.sql.ResultSet rs = ps.executeQuery();
            org.junit.jupiter.api.Assertions.assertTrue(rs.next());
            rs.getObject(1);
            org.junit.jupiter.api.Assertions.assertTrue(rs.wasNull());
        } catch (Exception e) { throw new RuntimeException(e); }

        // 그룹 자체도 삭제되어 더 이상 존재하지 않아야 한다
        try (java.sql.PreparedStatement ps = dbConnection.prepareStatement(
                "SELECT COUNT(*) FROM MEMBER_GROUP WHERE MEMBER_GROUP_SEQ IN (97771, 97772)")) {
            java.sql.ResultSet rs = ps.executeQuery();
            rs.next();
            org.junit.jupiter.api.Assertions.assertEquals(0, rs.getInt(1));
        } catch (Exception e) { throw new RuntimeException(e); }
    }

    // ==================== ATC — 필수 파라미터(memberGroupSeqs[]) 누락 ====================

    @Test @Order(3)
    void ATC_deleteGroup_missingRequiredParam() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().delete("/web/admin/quota/groups")
        .then().log().all().statusCode(200)
            .body("err", equalTo("999"));
    }

    // ==================== ATC — 세션 없이 호출 ====================

    @Test @Order(4)
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("memberGroupSeqs[]", 97771)
        .when().delete("/web/admin/quota/groups")
        .then().log().all().statusCode(401);
    }
}

