package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.MethodOrderer;
import org.junit.jupiter.api.Order;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestMethodOrder;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test — 가입자 트래픽 엑셀 다운로드 생성 (성공 경로 커버리지)
 *
 * @target-controller TrafficController (/web/admin/traffic)
 * @target-api POST /web/admin/traffic/excel/make
 *
 * NOTE: AdminTrafficBlackBoxTest는 AUTHZ='02'(일반 관리자) 세션만 사용하여
 * 이 엔드포인트가 AdminLoginInterceptor 블랙리스트에 의해 항상 403을 반환하는 것만 확인한다
 * (ATC_makeExcel_forbidden 등). 실제 AUTHZ='07'(SYSTEM) 계정으로 호출하는 성공 경로(err=000)는
 * 기존 스위트에 존재하지 않는다. TrafficService.makeTrafficExcel은 엑셀 생성 자체는
 * 백그라운드 쓰레드(fire-and-forget)로 수행하고 요청은 즉시 응답하므로, 이 테스트는
 * 동기적으로 관측 가능한 응답(err/excelReason 검증)에 집중한다.
 */
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class TrafficExcelMakeBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/traffic-excel-make-teardown.sql", TrafficExcelMakeBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/traffic-excel-make-setup.sql", TrafficExcelMakeBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "trafficexceladmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/traffic-excel-make-teardown.sql", TrafficExcelMakeBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    // ==================== NTC — 정산(CALCULATE) 데이터 타입 ====================

    @Test @Order(1)
    void NTC_makeExcel_calculate_success() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchDataType", "CALCULATE")
            .formParam("searchPeriodType", "SEARCH_FOR_MONTH")
            .formParam("searchTrafficType", "TOTAL")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260331")
            .formParam("excelReason", "정산 데이터 업무용 다운로드")
        .when().post("/web/admin/traffic/excel/make")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
    }

    // ==================== NTC — 실시간(REAL_TIME) 데이터 타입, CTN 검색 ====================

    @Test @Order(2)
    void NTC_makeExcel_realtime_ctnSearch_success() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchType", "CTN")
            .formParam("searchValue", "01099998888")
            .formParam("searchDataType", "REAL_TIME")
            .formParam("searchPeriodType", "SEARCH_FOR_DAY")
            .formParam("searchTrafficType", "UPLOAD")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260307")
            .formParam("excelReason", "실시간 데이터 감사용")
        .when().post("/web/admin/traffic/excel/make")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
    }

    // ==================== VTC — excelReason에 XSS 문자열 (SYSTEM 권한이라 인터셉터를 통과하여 실제 검증 도달) ====================

    @Test @Order(3)
    void VTC_excelReason_xss() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchDataType", "CALCULATE")
            .formParam("searchPeriodType", "SEARCH_FOR_MONTH")
            .formParam("searchTrafficType", "TOTAL")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260331")
            .formParam("excelReason", "<script>alert('xss')</script>")
        .when().post("/web/admin/traffic/excel/make")
        .then().log().all().statusCode(200)
            .body("err", equalTo("002"))
            .body("errMsg", equalTo("VULNERABLE_VALUE"));
    }

    // ==================== ATC — 세션 없이 호출 ====================

    @Test @Order(4)
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchDataType", "CALCULATE")
            .formParam("excelReason", "irrelevant")
        .when().post("/web/admin/traffic/excel/make")
        .then().log().all().statusCode(401);
    }
}

